css:
/* ============================================================
   cart and checkout
   ============================================================ */
/* the head and the content read as one band, so the two sets of band padding
   between them are pulled back to a single comfortable gap */
.co-head{background:linear-gradient(176deg,#ffffff 0%,#f4f7fb 100%);padding-bottom:0}
.co-head .eyebrow{margin-bottom:10px}
.co-head h1{margin:0 0 14px}
.co-head h1:last-child{margin-bottom:0}
.co-head .lede{max-width:62ch;margin:0}
.co-head+.band{background:#f4f7fb;padding-top:clamp(30px,3.4vw,48px)}

.co-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,.9fr);gap:clamp(22px,2.6vw,40px);align-items:start}
@media (max-width:1000px){.co-grid{grid-template-columns:1fr}}

/* ---- the cart table ---- */
.cartp{background:#fff;border:1px solid var(--line);border-radius:var(--r-card);box-shadow:var(--sh-1);overflow:hidden}
.cartp-head{display:grid;grid-template-columns:1fr 150px 130px;gap:16px;padding:16px clamp(18px,2.4vw,28px);
  background:var(--navy-900);color:var(--d-body);font-family:var(--ff-head);font-weight:600;font-size:.74rem;
  letter-spacing:.14em;text-transform:uppercase}
.cartp-head span:nth-child(2){text-align:center}
.cartp-head span:last-child{text-align:right}
@media (max-width:620px){.cartp-head{display:none}}

.cartp-list{list-style:none;margin:0;padding:0}
.cartp-list[hidden]{display:none}
.cartp-list>li{display:grid;grid-template-columns:96px 1fr 150px 130px;gap:16px;align-items:start;margin:0;
  padding:clamp(16px,2.2vw,22px) clamp(18px,2.4vw,28px);border-bottom:1px solid var(--line)}
.cartp-list>li:last-child{border-bottom:0}
.cartp-thumb{width:96px;height:96px;border-radius:var(--r);background:var(--paper-2);overflow:hidden;display:grid;place-items:center}
.cartp-thumb img{width:100%;height:100%;object-fit:contain;padding:8px}
.cartp-thumb svg{width:28px;height:28px;fill:var(--navy-300)}
.cartp-info{min-width:0}
.cartp-info h3{margin:0 0 5px;font-family:var(--ff-head);font-weight:600;font-size:1.02rem;line-height:1.35;color:var(--ink)}
.cartp-info h3 a{color:inherit;text-decoration:none}
.cartp-info h3 a:hover{color:var(--red-700)}
.cartp-meta{margin:0 0 8px;font-size:.84rem;color:var(--muted)}
.cartp-unit{margin:0;font-size:.84rem;color:var(--body)}
.cartp-qty{display:inline-flex;align-items:center;gap:2px;border:1px solid var(--line-2);border-radius:var(--r-sm);
  overflow:hidden;justify-self:center;margin-top:2px}
.cartp-qty button{width:38px;height:38px;border:0;background:#fff;color:var(--navy);cursor:pointer;
  font-family:var(--ff-head);font-weight:700;font-size:1.05rem;line-height:1;transition:background-color var(--t) var(--ease)}
.cartp-qty button:hover{background:var(--navy-50)}
.cartp-qty span{min-width:36px;text-align:center;font-family:var(--ff-head);font-weight:600;font-size:.95rem;color:var(--ink)}
.cartp-right{display:flex;flex-direction:column;align-items:flex-end;gap:9px}
.cartp-price{font-family:var(--ff-head);font-weight:700;font-size:1.08rem;color:var(--ink);white-space:nowrap}
.cartp-del{border:0;background:none;cursor:pointer;color:var(--muted);padding:5px;border-radius:var(--r-xs);
  display:inline-flex;align-items:center;gap:.4em;font-size:.8rem;transition:color var(--t) var(--ease)}
.cartp-del svg{width:14px;height:14px;fill:currentColor}
.cartp-del:hover{color:var(--red-700)}
@media (max-width:620px){
  .cartp-list>li{grid-template-columns:76px 1fr;row-gap:12px}
  .cartp-thumb{width:76px;height:76px}
  .cartp-qty{justify-self:start;grid-column:1 / -1}
  .cartp-right{grid-column:1 / -1;flex-direction:row;align-items:center;justify-content:space-between}
}

.cartp-empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:14px;
  padding:clamp(38px,7vw,64px) clamp(22px,5.5%,34px)}
.cartp-empty[hidden]{display:none}
.cartp-empty h2{margin:0;font-size:clamp(1.3rem,2vw,1.6rem)}
.cartp-empty p{margin:0;max-width:46ch}
.cartp-empty .btn{width:100%;max-width:330px}

.cartp-notes{list-style:none;margin:22px 0 0;padding:0;display:grid;gap:9px}
.cartp-notes li{display:flex;gap:.6em;align-items:flex-start;margin:0;font-size:.9rem;color:var(--body)}
.cartp-notes .ic{width:17px;height:17px;flex:none;margin-top:4px;color:#fff;background:var(--red);border-radius:50%;padding:4px;box-sizing:border-box}
.cartp-back{margin:24px 0 0}

/* ---- the summary rail ---- */
.co-side{background:var(--navy-50);border:1px solid var(--line);border-radius:var(--r-card);
  padding:clamp(22px,2.4vw,30px);position:sticky;top:clamp(96px,11vh,132px)}
@media (max-width:1000px){.co-side{position:static}}
.co-side-k{margin:0 0 16px;font-family:var(--ff-head);font-size:.78rem;letter-spacing:.16em;text-transform:uppercase;color:var(--navy)}
.co-lines{list-style:none;margin:0 0 16px;padding:0 0 16px;border-bottom:1px solid var(--line-2);display:grid;gap:13px}
.co-lines:empty{display:none}
.co-lines>li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;margin:0;align-items:start}
.co-lines>li>div{min-width:0}
.co-lines>li>div>b{font-family:var(--ff-head);font-weight:600;font-size:.93rem;color:var(--ink);line-height:1.38;display:block}
.co-lines>li>div>small{display:block;font-size:.8rem;color:var(--muted);margin-top:2px}
.co-lines>li>span{font-family:var(--ff-head);font-weight:700;font-size:.95rem;color:var(--ink);white-space:nowrap}
.co-empty{margin:0 0 16px;font-size:.9rem;color:var(--body)}
.co-empty[hidden]{display:none}

.co-sum{margin:0 0 18px}
.co-sum div{display:flex;align-items:baseline;justify-content:space-between;gap:16px;padding:7px 0}
.co-sum dt{margin:0;font-size:.92rem;color:var(--body)}
.co-sum dd{margin:0;font-family:var(--ff-head);font-weight:600;font-size:.95rem;color:var(--ink)}
.co-sum-total{border-top:1px solid var(--line-2);margin-top:8px;padding-top:14px}
.co-sum-total dt{font-family:var(--ff-head);font-weight:600;font-size:1.02rem;color:var(--ink)}
.co-sum-total dd{font-size:1.42rem;font-weight:700}
.co-go{width:100%;min-height:58px}
.co-go[aria-disabled="true"]{opacity:.45;pointer-events:none}
.co-note{margin:14px 0 0;font-size:.82rem;color:var(--muted);line-height:1.6}
.co-help{margin:14px 0 0;font-size:.88rem}
.co-side .buy-trust{margin-top:18px}

/* ---- the checkout form ---- */
.co-form{display:grid;gap:clamp(18px,2.2vw,26px)}
.co-step{border:1px solid var(--line);border-radius:var(--r-card);background:#fff;padding:clamp(20px,2.4vw,30px);margin:0;box-shadow:var(--sh-1)}
.co-step legend{display:flex;align-items:center;gap:.7em;padding:0 10px;margin-left:-10px;
  font-family:var(--ff-head);font-weight:600;font-size:clamp(1.02rem,1.3vw,1.18rem);color:var(--ink)}
.co-n{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--navy);color:#fff;
  font-size:.86rem;font-weight:700;flex:none}
.co-pay .co-payline{display:flex;gap:14px;align-items:flex-start;background:var(--navy-50);
  border:1px solid var(--line-2);border-radius:var(--r);padding:18px 20px}
.co-pay .ic-md{width:34px;height:34px;flex:none;color:#fff;background:var(--red);border-radius:50%;padding:8px;box-sizing:border-box}
.co-pay h3{margin:0 0 5px;font-family:var(--ff-head);font-weight:600;font-size:1.02rem;color:var(--ink)}
.co-pay p{margin:0;font-size:.91rem}
.co-paynote{margin:14px 0 0;font-size:.85rem;color:var(--muted)}
.co-submit{width:100%;min-height:62px;font-size:1.04rem}
.co-fine{margin:12px 0 0;text-align:center;font-size:.85rem;color:var(--muted)}

/* ---- the options the customer chose ---- */
.cartp-opts,.co-opts{list-style:none;margin:9px 0 0;padding:0 0 0 13px;display:grid;gap:5px;
  border-left:2px solid var(--line-2)}
.cartp-opts li,.co-opts li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:baseline;
  margin:0;font-size:.83rem;line-height:1.5;color:var(--body)}
.cartp-opts span,.co-opts span{min-width:0;overflow-wrap:anywhere}
.cartp-opts b,.co-opts b{font-family:var(--ff-head);font-weight:600;color:var(--ink);white-space:nowrap}
.co-opts{margin-top:7px;gap:4px}
.co-opts li{font-size:.79rem}
.cartp-each{margin-top:11px;color:var(--muted);font-size:.82rem}
.co-unit{margin:4px 0 0;font-size:.79rem;color:var(--muted)}
